import AVFoundation
import XCTest
@testable import TygerVoice
@testable import TygerVoiceMLX

/// End-to-end numeric parity for the mac tier: the Swift MLX chain over a real
/// conversation slice vs the accepted Python chain's per-frame 8-vectors
/// (fixtures generated by `scripts/tyger-swift-fixtures.py --mlx`, prev_state
/// held at 0 — the rules threading is covered by the Rust fixture suite).
final class MlxRuntimeTests: XCTestCase {
    func testRuntimeMatchesTheAcceptedMlxChain() throws {
        let here = URL(fileURLWithPath: #filePath)
        let pkg = here.deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
        let weights = pkg.deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("bench-results/mlx/TygerChainInt8.safetensors")
        guard FileManager.default.fileExists(atPath: weights.path) else {
            throw XCTSkip("accepted weights not exported (ports/tyger-mlx/export_swift.py)")
        }
        let fxDir = pkg.appendingPathComponent("Tests/TygerVoiceTests/runtime")
        let exp = try JSONDecoder().decode(
            Expectations.self, from: try Data(contentsOf: fxDir.appendingPathComponent("expectations-mlx.json")))
        let user = try readWav(fxDir.appendingPathComponent("ch0.wav"))
        let agent = try readWav(fxDir.appendingPathComponent("ch1.wav"))

        let rt = TurnRuntime(model: try MlxTurnModel(weightsURL: weights))
        var got: [[Float]] = []
        var h = 0
        while (h + 1) * exp.hopSamples <= min(user.count, agent.count) {
            let s = h * exp.hopSamples
            got.append(contentsOf: rt.feed(
                userHop: Array(user[s..<s + exp.hopSamples]),
                agentHop: Array(agent[s..<s + exp.hopSamples]),
                prevState: { _ in 0 }))
            h += 1
        }
        XCTAssertEqual(got.count, exp.frames.count, "frame count")
        // The Swift chain reproduces the accepted Python chain to ~1e-5 (model
        // arithmetic + the MelFeatures featurizer). A wiring bug is O(1); the
        // budget stays orders of magnitude above the drift and far below that.
        let envelope: [Double] = [1e-4, 1e-4, 1e-4, 1e-4, 1e-4, 1e-4, 1e-4, 1e-4]
        var worst = [Double](repeating: 0, count: 8)
        var sum = [Double](repeating: 0, count: 8)
        for (g, w) in zip(got, exp.frames) {
            for k in 0..<8 {
                let d = abs(Double(g[k]) - w[k])
                worst[k] = max(worst[k], d)
                sum[k] += d
            }
        }
        for k in 0..<8 {
            let mean = sum[k] / Double(exp.frames.count)
            XCTAssertLessThanOrEqual(worst[k], envelope[k], "head \(k) max")
            XCTAssertLessThanOrEqual(mean, 2e-5, "head \(k) mean (wiring check)")
        }
    }

    struct Expectations: Decodable {
        let hopSamples: Int
        let frames: [[Double]]
        enum CodingKeys: String, CodingKey { case hopSamples = "hop_samples", frames }
    }

    private func readWav(_ url: URL) throws -> [Float] {
        let f = try AVAudioFile(forReading: url)
        let n = AVAudioFrameCount(f.length)
        let fmt = f.processingFormat
        let buf = AVAudioPCMBuffer(pcmFormat: fmt, frameCapacity: n)!
        try f.read(into: buf)
        let ch = buf.floatChannelData![0]
        return (0..<Int(n)).map { ch[$0] }
    }
}
